# Let me trace through each transformation one by one to understand the pattern better
inputs = ['ywjggv', 'xdcc', 'vxwdc', 'behfg', 'hck']
outputs = ['ywjggv', 'zhdcc', 'vzhwdc', 'behzhg', 'hck']

print("Detailed analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"{inp} -> {outp}")
    # Show character by character comparison
    min_len = min(len(inp), len(outp))
    for j in range(max(len(inp), len(outp))):
        in_char = inp[j] if j < len(inp) else None
        out_char = outp[j] if j < len(outp) else None
        if in_char != out_char:
            print(f"  Position {j}: '{in_char}' -> '{out_char}'")
    print()

# Now let's identify unique character transformations
transformations = {}
for inp, outp in zip(inputs, outputs):
    min_len = min(len(inp), len(outp))
    for j in range(min_len):
        if inp[j] != outp[j]:
            transformations[inp[j]] = outp[j]

print("Character transformations:")
for char, replacement in transformations.items():
    print(f"  '{char}' -> '{replacement}'")

